npcs
people_black_belt 3 2 S static 0 LOCALID_FALLARBOR_TENT_BATTLE_ATTENDANT
onload
VAR_TEMP_0 0 FallarborTown_BattleTentBattleRoom_EventScript_EnterRoom
movements
FallarborTown_BattleTentBattleRoom_Movement_AttendantApproachPlayer	down,down,down,delay,end
FallarborTown_BattleTentBattleRoom_Movement_AttendantJump	delay,delay,end
FallarborTown_BattleTentBattleRoom_Movement_AttendantReturnToPos	up,up,up,delay,end
